INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4637958, 669090, 24976, '<td valign="top">imo the colors are too saturated and vivid.</td>', 'imo the colors are too saturated and vivid.', '2008-04-14 02:47:18.000000', NULL, 1),
(4637960, 668988, 108564, '<td valign="top">Spectacular!</td>', 'Spectacular!', '2008-04-14 02:47:52.000000', NULL, 1),
(4637961, 669160, 24976, '<td valign="top">imo u should have used the darker blue from the sky on the water as well. the bright blue in the foreground seems a bit out of place.</td>', 'imo u should have used the darker blue from the sky on the water as well. the bright blue in the foreground seems a bit out of place.', '2008-04-14 02:48:33.000000', NULL, 1),
(4637962, 668751, 38930, '<td valign="top">WOW!  I hope you tell us how you did this - I love the ripples.  The blue is turning me off a little...did you try this with a black bowl??  9</td>', 'WOW!  I hope you tell us how you did this - I love the ripples.  The blue is turning me off a little...did you try this with a black bowl??  9', '2008-04-14 02:48:34.000000', NULL, 1),
(4637963, 669188, 24976, '<td valign="top">lovely. 10</td>', 'lovely. 10', '2008-04-14 02:49:02.000000', NULL, 1),
(4637965, 668698, 38930, '<td valign="top">Good job with this macro!  Next time you might try looking more up towards the sky so you have less grass in the background.  Or just up a little more so the ''main'' grass and the background aren''t overlapping.  Good job though</td>', 'Good job with this macro!  Next time you might try looking more up towards the sky so you have less grass in the background.  Or just up a little more so the ''main'' grass and the background aren''t overlapping.  Good job though', '2008-04-14 02:52:14.000000', NULL, 1),
(4637966, 669087, 24976, '<td valign="top">only critism would be that some of the green leaves are getting a bit too vivid... but still a solid 9</td>', 'only critism would be that some of the green leaves are getting a bit too vivid... but still a solid 9', '2008-04-14 02:52:46.000000', NULL, 1),
(4637967, 668065, 38930, '<td valign="top">Thaaaaat is gross.</td>', 'Thaaaaat is gross.', '2008-04-14 02:52:54.000000', NULL, 1),
(4637969, 669014, 38930, '<td valign="top">Cool location!  Try shooting later (or earlier) in the day next time so the light isn''t so harsh.  This picture surely meets the challenge!</td>', 'Cool location!  Try shooting later (or earlier) in the day next time so the light isn''t so harsh.  This picture surely meets the challenge!', '2008-04-14 02:53:58.000000', NULL, 1),
(4637970, 666967, 66515, '<td valign="top">Yeah...not really related to this challenge at all. You have a pail of water but this shot doesn''t have anything to do with water. That aside, its an interesting spring ritual and I have taken part in it myself. Too bad you didn''t get a picture of his head.</td>', 'Yeah...not really related to this challenge at all. You have a pail of water but this shot doesn''t have anything to do with water. That aside, its an interesting spring ritual and I have taken part in it myself. Too bad you didn''t get a picture of his head.', '2008-04-14 02:54:39.000000', NULL, 1),
(4637972, 668753, 38930, '<td valign="top">Ooooh...is this in Hawaii?  If you can, try bringing the levels up on this a little more so it''s a bit brighter.  Good composition!</td>', 'Ooooh...is this in Hawaii?  If you can, try bringing the levels up on this a little more so it''s a bit brighter.  Good composition!', '2008-04-14 02:56:05.000000', NULL, 1),
