(4638554, 668527, 69368, '<td valign="top">oh, I have to look twice....<br/>Really creative idea! Very well done!</td>', 'oh, I have to look twice....Really creative idea! Very well done!', '2008-04-14 12:10:20.000000', NULL, 1),
(4638557, 669113, 58457, '<td valign="top">Those are some ominous clouds!  Great sky, and a good photo.  For a water challenge, this does become a bit more about the sky than the water though...  hmmm... 7.</td>', 'Those are some ominous clouds!  Great sky, and a good photo.  For a water challenge, this does become a bit more about the sky than the water though...  hmmm... 7.', '2008-04-14 12:12:11.000000', NULL, 1),
(4638576, 669051, 61971, '<td valign="top">I like the concept. I think this would have been stronger for me if there was a tighter crop on the right, which would leave a great line through the picture with the wave, and a little bit brighter, or black and white.</td>', 'I like the concept. I think this would have been stronger for me if there was a tighter crop on the right, which would leave a great line through the picture with the wave, and a little bit brighter, or black and white.', '2008-04-14 12:31:32.000000', NULL, 1),
(4638579, 669110, 61971, '<td valign="top">I like the old feel to this but I feel like the glow makes the building and sky just a little bright and pulls my eyes from the water</td>', 'I like the old feel to this but I feel like the glow makes the building and sky just a little bright and pulls my eyes from the water', '2008-04-14 12:32:58.000000', NULL, 1),
(4638672, 669056, 43774, '<td valign="top">This looks a lot like Newfoundland</td>', 'This looks a lot like Newfoundland', '2008-04-14 13:30:17.000000', NULL, 1),
(4638681, 668946, 43774, '<td valign="top">Edmonton, right? Very very nice.</td>', 'Edmonton, right? Very very nice.', '2008-04-14 13:44:13.000000', NULL, 1),
(4638682, 669054, 43774, '<td valign="top">Oh wow! My aunt and uncle worked here when I was a kid in the 70''s.....they were our popular aunt and uncle who lived in the USA and would come home to Newfoundland for vacations. Thanks for the memories!</td>', 'Oh wow! My aunt and uncle worked here when I was a kid in the 70''s.....they were our popular aunt and uncle who lived in the USA and would come home to Newfoundland for vacations. Thanks for the memories!', '2008-04-14 13:44:41.000000', NULL, 1),
