(4638720, 668214, 24550, '<td valign="top">awesome textures and colors, but i think you JUST missed the focus, unfortunately. still, pretty good.</td>', 'awesome textures and colors, but i think you JUST missed the focus, unfortunately. still, pretty good.', '2008-04-14 14:13:11.000000', NULL, 1),
(4638722, 669078, 24550, '<td valign="top">the reflections are nice, but the buildings are blending into the sky a bit up top.</td>', 'the reflections are nice, but the buildings are blending into the sky a bit up top.', '2008-04-14 14:13:37.000000', NULL, 1),
(4638723, 669167, 24550, '<td valign="top">nice portrait, well focused and composed.</td>', 'nice portrait, well focused and composed.', '2008-04-14 14:13:54.000000', NULL, 1),
(4638726, 668340, 24550, '<td valign="top">good idea, colors, and composition, but the droplet isn''t as sharp as it should be for a shot like this which is essentially aiming to move our eye down the leaf to the drop itself in a fluid motion. the eye should "stick" once it reaches the drop, and the only way that can happen is with razor sharp focus. still, these shots are tough and i haven''t ever been able to pull them off very well.</td>', 'good idea, colors, and composition, but the droplet isn''t as sharp as it should be for a shot like this which is essentially aiming to move our eye down the leaf to the drop itself in a fluid motion. the eye should "stick" once it reaches the drop, and the only way that can happen is with razor sharp focus. still, these shots are tough and i haven''t ever been able to pull them off very well.', '2008-04-14 14:16:04.000000', NULL, 1),
(4638727, 669188, 24550, '<td valign="top">awesome symmetry, and love the fade to black.</td>', 'awesome symmetry, and love the fade to black.', '2008-04-14 14:16:23.000000', NULL, 1),
