(4645102, 669185, 63503, '<td valign="top">Wow!! what a capture!!</td>', 'Wow!! what a capture!!', '2008-04-17 01:16:03.000000', NULL, 1),
(4645105, 669008, 63503, '<td valign="top">Great colors but I am not sure I like the extreme wide angle distortion.</td>', 'Great colors but I am not sure I like the extreme wide angle distortion.', '2008-04-17 01:19:07.000000', NULL, 1),
(4645124, 667795, 38930, '<td valign="top">This is great!  How is the water not spilling out?</td>', 'This is great!  How is the water not spilling out?', '2008-04-17 01:37:23.000000', NULL, 1),
